correct

{noformat}select 
		count(distinct case when searches in (1,2) then session_id else null end) searches_without_zoom,
		count(distinct case when searches>=3 then session_id else null end) searches_with_zoom
from (
select session_id,min(created) min_created,max(created) max_created,count(*) searches
from rental.rental_search_categories_overview
where created_date between date'2023-09-01' and date'2023-10-01'
group by 1
){noformat}

